        new("Appetizers", "appetizers", "Starters and snacks perfect for entertaining."),
        new("Soups & Salads", "soups-salads", "Light and refreshing options for any season."),
        new("Vegetarian", "vegetarian", "Delicious meat-free meals packed with flavor.")
    ];

    private record CategoryInfo(string Name, string Slug, string Description);
}

