@page "/category/{Slug}"

<PageTitle>@GetCategoryName() - RecipeHub</PageTitle>

<h1>@GetCategoryName()</h1>
<p><a href="/">← Back to Categories</a></p>

@if (GetRecipes() is { Length: > 0 } recipes)
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">@recipe.Summary</p>
                        <a href="@($"recipe/{recipe.Id}")" class="btn btn-outline-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p class="text-muted">No recipes in this category yet. <a href="/submit">Submit one!</a></p>
}

@code {
    [Parameter] public string Slug { get; set; } = "";

    private string GetCategoryName() => Slug switch
    {
        "breakfast" => "Breakfast",
        "main-courses" => "Main Courses",
        "desserts" => "Desserts",
        "appetizers" => "Appetizers",
        "soups-salads" => "Soups & Salads",
        "vegetarian" => "Vegetarian",
        _ => "Category"
    };

    private RecipeInfo[] GetRecipes() => Slug switch
    {
        "breakfast" =>
        [
            new(1, "Fluffy Pancakes", "Light and airy pancakes with maple syrup."),
            new(2, "Avocado Toast", "Crispy toast topped with smashed avocado and poached egg.")
        ],
        "main-courses" =>
        [
            new(3, "Spaghetti Carbonara", "Classic Italian pasta with creamy egg sauce and pancetta."),
            new(4, "Chicken Tikka Masala", "Tender chicken in a rich, spiced tomato cream sauce.")
        ],
        "desserts" =>
        [
            new(5, "Chocolate Lava Cake", "Warm cake with a molten chocolate center."),
            new(6, "Tiramisu", "Italian coffee-flavored layered dessert.")
        ],
        "appetizers" =>
        [
            new(7, "Bruschetta", "Toasted bread topped with fresh tomatoes, basil, and garlic.")
        ],
        "soups-salads" =>
        [
            new(8, "Tomato Basil Soup", "Creamy tomato soup with fresh basil and a hint of garlic.")
        ],
        "vegetarian" =>
        [
            new(9, "Mushroom Risotto", "Creamy Arborio rice with wild mushrooms and Parmesan.")
        ],
        _ => []
    };

    private record RecipeInfo(int Id, string Title, string Summary);
}

@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= CurrentRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              role="button"
              title="@star star(s)">
            @(star <= CurrentRating ? "★" : "☆")
        </span>
    }
    @if (CurrentRating > 0)
    {
        <span class="ms-2 text-muted">You rated this @CurrentRating/5</span>
    }
    else
    {
        <span class="ms-2 text-muted">Click to rate</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int CurrentRating { get; set; }

    private void Rate(int rating)
    {
        CurrentRating = rating;
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (IsSubmitted)
{
    <div class="alert alert-success">
        <h4>Thank you!</h4>
        <p>Your recipe "<strong>@Model.Title</strong>" has been submitted for review.</p>
        <a href="/" class="btn btn-primary">Back to Home</a>
    </div>
}
else
{
    <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" @bind-Value="Model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => Model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" @bind-Value="Model.Category" class="form-select">
                <option value="">-- Select a category --</option>
                <option value="breakfast">Breakfast</option>
                <option value="main-courses">Main Courses</option>
                <option value="desserts">Desserts</option>
                <option value="appetizers">Appetizers</option>
                <option value="soups-salads">Soups & Salads</option>
                <option value="vegetarian">Vegetarian</option>
            </InputSelect>
            <ValidationMessage For="() => Model.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients (one per line)</label>
            <InputTextArea id="ingredients" @bind-Value="Model.Ingredients" class="form-control" rows="6" placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => Model.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="Model.Steps" class="form-control" rows="6" placeholder="Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
            <ValidationMessage For="() => Model.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeSubmission Model { get; set; } = new();
    private bool IsSubmitted { get; set; }

    private void HandleSubmit()
    {
        IsSubmitted = true;
    }

    private class RecipeSubmission
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please enter a recipe title.")]
        [System.ComponentModel.DataAnnotations.StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be between 3 and 100 characters.")]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please list the ingredients.")]
        public string Ingredients { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please describe the steps.")]
        public string Steps { get; set; } = "";
    }
}

